insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('housing-grammar','W mieszkaniu nie ma ___.','["ciepła woda","ciepłej wody","ciepłą wodą"]',1,'После nie ma употребляется родительный падеж: ciepłej wody.',0),
('housing-grammar','Szukamy małego ___.','["mieszkanie","mieszkaniem","mieszkania"]',2,'Глагол szukać требует родительного падежа: szukamy mieszkania.',1),
('housing-grammar','Mamy problem z ___.','["ogrzewaniem","ogrzewania","ogrzewanie"]',0,'После z в значении «с чем?» нужен творительный падеж: z ogrzewaniem.',2),
('housing-grammar','Разговариваю с владельцем.','["Rozmawiam z właścicielem.","Rozmawiam z właściciela.","Rozmawiam właściciel."]',0,'После z в значении совместности употребляется творительный: z właścicielem.',3),
('housing-grammar','Potrzebujemy ___.','["hydraulik","hydraulika","hydraulikiem"]',1,'Potrzebować требует родительного падежа: potrzebujemy hydraulika.',4),
('housing-quiz','Что означает kaucja?','["отопление","залог","счётчик"]',1,'Kaucja — залог, который обычно возвращают после окончания аренды.',0),
('housing-quiz','Nie ma ___.','["prądu","prądem","prąd"]',0,'Отрицательная конструкция nie ma требует родительного: prądu.',1),
('housing-quiz','Problem z ___.','["kran","kranu","kranem"]',2,'После z в конструкции problem z нужен творительный: kranem.',2),
('housing-quiz','Куда сообщить о неисправности?','["Zgłosić usterkę administracji.","Wynająć hydraulika umową.","Szukać czynsz z wodą."]',0,'Zgłosić usterkę administracji — сообщить управляющей компании о неисправности.',3),
('housing-quiz','Szukamy ___.','["nowego mieszkania","nowym mieszkaniem","nowe mieszkanie"]',0,'Szukać управляет родительным падежом: nowego mieszkania.',4),
('housing-quiz','Rozmawiam z ___.','["hydraulika","hydraulikiem","hydraulik"]',1,'Лицо после z ставится в творительном падеже: z hydraulikiem.',5),
('housing-quiz','Что обычно подписывают при аренде?','["usterkę","umowę","ogrzewanie"]',1,'При аренде стороны подписывают umowę — договор.',6),
('housing-quiz','Ustaliliśmy ___ naprawy.','["termin","czynszem","kaucji nie ma"]',0,'Ustalić termin naprawy — назначить время ремонта.',7),
('housing-reading-check','Jaki problem zauważyła Lena?','["Nie działało ogrzewanie","Zgubiła umowę","Nie miała kluczy"]',0,'Утром Лена заметила, что отопление не работает.',0),
('housing-reading-check','Do kogo Lena najpierw zadzwoniła?','["Do koleżanki","Do właściciela","Do hydraulika"]',1,'Сначала она позвонила владельцу квартиры.',1),
('housing-reading-check','Dlaczego właściciel poprosił o wiadomość?','["Potrzebował opisu usterki","Chciał podnieść czynsz","Szukał nowego mieszkania"]',0,'Ему нужны были описание проблемы и фотография счётчика.',2),
('housing-reading-check','Kiedy fachowiec ma przyjść?','["W poniedziałek rano","We wtorek między 16 a 18","W niedzielę wieczorem"]',1,'Администрация назначила визит на вторник с 16 до 18.',3),
('housing-reading-check','Co Lena zrobi, jeśli naprawa się opóźni?','["Wyprowadzi się natychmiast","Podpisze nową umowę","Ponownie skontaktuje się z administracją"]',2,'Если специалист не придёт вовремя, она снова свяжется с администрацией.',4);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values
('usterka-w-mieszkaniu','housing-services','Usterka w mieszkaniu','Лена договаривается о ремонте отопления','A2',5,'🔧','["Lena wynajmuje małe mieszkanie w Poznaniu. W poniedziałek rano zauważyła, że ogrzewanie nie działa, a w sypialni jest bardzo zimno. Najpierw zadzwoniła do właściciela. Powiedziała, że od wieczora nie ma ciepłych kaloryferów i potrzebuje szybkiej pomocy.","Właściciel poprosił Lenę o krótką wiadomość z opisem usterki i zdjęciem licznika. Potem zgłosił problem administracji. Po godzinie administracja odpowiedziała, że fachowiec może przyjść we wtorek między szesnastą a osiemnastą. Lena potwierdziła termin i zapytała, czy naprawa będzie płatna.","Zgodnie z umową właściciel zapłaci za naprawę ogrzewania. Lena będzie rozmawiać z fachowcem i pokaże mu kaloryfer w sypialni. Jeśli fachowiec się spóźni, ponownie skontaktuje się z administracją. Lena ma nadzieję, że wieczorem mieszkanie znów będzie ciepłe."]','{"wynajmuje":{"lemma":"wynajmować","translation":"снимать","part_of_speech":"глагол"},"zauważyła":{"lemma":"zauważyć","translation":"заметить","part_of_speech":"глагол"},"ogrzewanie":{"lemma":"ogrzewanie","translation":"отопление","part_of_speech":"существительное"},"kaloryferów":{"lemma":"kaloryfer","translation":"радиатор","part_of_speech":"существительное"},"usterki":{"lemma":"usterka","translation":"неисправность","part_of_speech":"существительное"},"licznika":{"lemma":"licznik","translation":"счётчик","part_of_speech":"существительное"},"fachowiec":{"lemma":"fachowiec","translation":"специалист","part_of_speech":"существительное"},"potwierdziła":{"lemma":"potwierdzić","translation":"подтвердить","part_of_speech":"глагол"},"płatna":{"lemma":"płatny","translation":"платный","part_of_speech":"прилагательное"},"zgodnie":{"lemma":"zgodnie z","translation":"согласно","part_of_speech":"выражение"},"spóźni":{"lemma":"spóźnić się","translation":"опоздать","part_of_speech":"глагол"},"ponownie":{"lemma":"ponownie","translation":"повторно","part_of_speech":"наречие"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28","comprehension_lesson_id":"housing-reading-check"}',14,true)
